@startuml

class Person {
  + FirstName : string
  + LastName : string
  + BirthDate : date
}

abstract class Role {}

class Member {}
class Trainer {}
class Prospect {}
class Intern {}

class Center {
  + Name : string
  + Address : string
}

class Room {
  + Number : int
  + Capacity : int
}

class Session {
  + Date : date
  + StartHour : time
}

abstract class GroupSession extends Session {
  + Type : string
}

class IndividualSession extends Session {}

class TrainerSupervision {
  + Trainer : Trainer
}

GroupSession "1" -- "*" TrainerSupervision
IndividualSession "0..1" -- "*" TrainerSupervision

Person "1" *-- "0..2 roles" Role
Role "1" -- "1" Person

Member --|> Role
Trainer --|> Role
Prospect --|> Role
Intern --|> Role

Center "1" *-- "*" Room
Room "1" *-- "*" Session

@enduml

